#include <vector>
#include <algorithm>

class Solution {
public:
    long long maxSubarraySumMultiplier(std::vector<int>& nums, int multiplier) {
        long long s0 = 0, s1 = 0, s2 = 0, best = -1e18;
        for (int x : nums) {
            s0 = std::max((long long)x, s0 + x);
            s1 = std::max({(long long)x * multiplier, s0, s1 + (long long)x * multiplier});
            s2 = std::max({(long long)x, s1, s2 + x});
            best = std::max({best, s0, s1, s2});
        }
        return best;
    }
};

class Solution {
    public long maxSubarraySumMultiplier(int[] nums, int multiplier) {
        long s0 = 0, s1 = 0, s2 = 0, best = Long.MIN_VALUE;
        for (int x : nums) {
            s0 = Math.max(x, s0 + x);
            s1 = Math.max((long)x * multiplier, Math.max(s0, s1 + (long)x * multiplier));
            s2 = Math.max(x, Math.max(s1, s2 + x));
            best = Math.max(best, Math.max(s0, Math.max(s1, s2)));
        }
        return best;
    }
}

function maxSubarraySumMultiplier(nums, multiplier) {
    let s0 = 0, s1 = 0, s2 = 0, best = -Infinity;
    for (const x of nums) {
        s0 = Math.max(x, s0 + x);
        s1 = Math.max(x * multiplier, s0, s1 + x * multiplier);
        s2 = Math.max(x, s1, s2 + x);
        best = Math.max(best, s0, s1, s2);
    }
    return best;
}
